export default function DemoInteractive({slug}:{slug:string}) {
  const config = C[slug] ?? C.technology;
  const [query,setQuery] = useState("");
  const [selected,setSelected] = useState<string[]>([]);
  const [submitted,setSubmitted] = useState(false);
  const [open,setOpen] = useState<number | null>(0);
  const [name,setName] = useState("");
  const [email,setEmail] = useState("");
  const [message,setMessage] = useState("");
  const filtered = useMemo(()=>config.items.filter(item => (item.title+" "+item.description+" "+item.meta).toLowerCase().includes(query.toLowerCase())),[config,query]);
  const toggle = (title:string) => setSelected(old => old.includes(title) ? old.filter(x=>x!==title) : [...old,title]);
  return <div className="demo-interactive">
    <section className="demo-live-catalog" id="catalogue">
      <div className="demo-live-heading"><div><p className="demo-kicker">{config.eyebrow}</p><h2>{config.heading}</h2><p>{config.intro}</p></div><div className="demo-live-count"><b>{config.items.length.toString().padStart(2,"0")}</b><span>FEATURED OPTIONS</span></div></div>
      <div className="demo-live-toolbar"><label className="demo-live-search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search this demo..." aria-label="Search demo content"/></label><span>{filtered.length} of {config.items.length} shown</span><button type="button" onClick={()=>{setQuery("");setSelected([])}}>Reset preview</button></div>
      <div className="demo-live-grid">{filtered.map((item,i)=><article className="demo-live-card" key={item.title}><div className="demo-live-card-top"><span>{String(i+1).padStart(2,"0")}</span><span>{item.meta}</span></div><div className="demo-live-art"><i></i><i></i><i></i><b>{item.title}</b></div><div className="demo-live-card-copy"><h3>{item.title}</h3><p>{item.description}</p><div className="demo-live-card-bottom">{item.price && <strong>{item.price}</strong>}<button type="button" className={selected.includes(item.title)?"is-selected":""} onClick={()=>toggle(item.title)}>{selected.includes(item.title)?"✓ Added":"＋ Add to enquiry"}</button></div></div></article>)}</div>
      {filtered.length===0 && <p className="demo-live-empty">No matching items. Try another search term.</p>}
      <div className="demo-live-selection"><div><b>{selected.length} selected</b><span>{selected.length?selected.join(" · "):"Add options above to build an enquiry list."}</span></div><button type="button" onClick={()=>document.getElementById("demo-enquiry")?.scrollIntoView({behavior:"smooth"})} disabled={!selected.length}>Continue to enquiry ↘</button></div>
    </section>
    <section className="demo-live-benefits"><div><p className="demo-kicker">WHAT THIS WEBSITE CAN INCLUDE</p><h2>Useful tools, clear information and a better customer journey.</h2></div><div className="demo-live-benefit-grid">{config.benefits.map((x,i)=><article key={x}><b>0{i+1}</b><span>{x}</span></article>)}</div></section>
    <section className="demo-live-faq"><div><p className="demo-kicker">QUICK ANSWERS</p><h2>Frequently asked questions</h2><p>These sample answers can be rewritten with your real business policies and information.</p></div><div className="demo-live-faq-list">{config.questions.map((q,i)=><article key={q} className={open===i?"active":""}><button type="button" onClick={()=>setOpen(open===i?null:i)}><span>{q}</span><b>{open===i?"−":"＋"}</b></button>{open===i&&<p>This is a preview interaction. The final website can display your approved details, terms, timings and customer support information here.</p>}</article>)}</div></section>
    <section className="demo-live-enquiry" id="demo-enquiry"><div><p className="demo-kicker">TAKE THE NEXT STEP</p><h2>{config.action}</h2><p>Try the sample enquiry form. This preview stores nothing and does not send a real booking, order or payment.</p><div className="demo-live-contact-points"><span>✓ Mobile-friendly form</span><span>✓ Selected items included</span><span>✓ Custom fields available</span></div></div>
      <form onSubmit={e=>{e.preventDefault();setSubmitted(true)}}><label>Your name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Enter your name"/></label><label>Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>What would you like to know?<textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Tell us a little about your requirements..."/></label><div className="demo-live-form-selection"><b>Selected options</b><span>{selected.length?selected.join(", "):"No options selected"}</span></div><button type="submit">Submit sample enquiry ↗</button>{submitted&&<p className="demo-live-success" role="status">Sample completed successfully. No information was sent or stored. Your customised website can connect this form to a real inbox or CRM.</p>}</form>
    </section>
  </div>;
}
